#include <iostream>
#include <cstdio>
using namespace std;

int a[100001];

inline int read()
{
    bool f = false;
    int c = getchar();
    int x = 0;

    while (c != '-' && (c < '0' || c > '9'))
        c = getchar();

    if (c == '-')
    {
        f = true;
        c = getchar();
    }

    while (c >= '0' && c <= '9')
    {
        x = x * 10 + c - '0';
        c = getchar();
    }

    return f ? -x : x;
}

inline void write(int n)
{
    if (n < 0)
    {
        putchar('-');
        n = -n;
    }

    if (n >= 10)
        write(n / 10);

    putchar(n % 10 + '0');
}

int main()
{
    int n = read();
    int k = read();
    int ans = 0x7fffffff;

    for (int i = 1; i <= n; ++i)
    {
        a[i] = read();
        if (a[i] != 0 && k % a[i] == 0 && k / a[i] < ans)
            ans = k / a[i];
    }

    write(ans);
    return 0;
}

